let staleRefused = false;
try { await tools.write({path, content:'must not publish\n', ifVersion:first.version}); }
catch (error) { staleRefused = error.class === 'conflict'; }
if (!staleRefused) throw new Error('stale version published');
await tools.write({path, content:'final\n', ifVersion:written.version});
export default {sameCodec:first.version === moduleFile.version, changed:written.version !== first.version, current:current.version === written.version, pinned:pinned.text === 'first\n', staleRefused};
